    // ============================================
    // PROYECTO: MINCETUR - CONSTRUCCIÓN FUTURA
    // ============================================

    "project.mincetur.hero-title": "MINCETUR — Construcción Futura",
    "project.mincetur.hero-subtitle":
      "Taller intensivo de 3 días con líderes de CITE de todo Perú para co-crear un modelo de gestión replicable. Herramientas diseñadas seguían en uso 2 años después.",

    "project.mincetur.context-text-1":
      "Este proyecto fue un taller intensivo de 3 días solicitado por el <strong>Ministerio de Comercio Exterior y Turismo (MINCETUR)</strong> de Perú, con el objetivo de acompañar a los líderes de los <strong>CITE (Centros de Innovación Productiva y Transferencia Tecnológica)</strong> en la construcción de un modelo de gestión replicable y alineado con los requerimientos del Estado.",
    "project.mincetur.context-text-2":
      "Los CITE son centros estratégicos que impulsan la innovación en sectores como artesanía y turismo, pero enfrentaban desafíos para estructurar sus planes de gestión, optimizar el uso de presupuestos y cumplir con los KPIs exigidos por el gobierno. El taller buscaba traducir el lenguaje técnico estatal en un formato accesible y útil para los líderes de estos centros.",
    "project.mincetur.context-text-3":
      "Trabajando desde <strong>Creative Lab</strong>, creamos herramientas propias, adaptamos otras existentes y facilitamos todo el proceso de principio a fin. A través de dinámicas colaborativas, ayudamos a los participantes a interpretar datos, definir metas y visualizar de forma clara sus hojas de ruta.",
    "project.mincetur.context-note":
      "<strong>Nota personal:</strong> Este fue uno de mis primeros proyectos como Service Designer, y fue una experiencia formativa invaluable sobre facilitación intensiva y diseño de herramientas estratégicas.",

    "project.mincetur.challenge-text":
      "Diseñar y facilitar un taller intensivo de 3 días que permitiera a líderes de CITE de todo Perú co-crear un modelo de gestión replicable, traduciendo los complejos requerimientos del Estado en herramientas prácticas y accesibles que pudieran implementar inmediatamente.",

    "project.mincetur.role-text":
      "Participé como <strong>Service Designer en Creative Lab</strong>, siendo la más junior del equipo de 4 personas. Este fue uno de mis primeros proyectos profesionales, y me permitió aprender sobre facilitación de talleres intensivos y diseño estratégico en contextos gubernamentales.",

