    // ============================================
    // CUBICO - LA GESTION DEL PROYECTO
    // ============================================
    "project.cubico.mgmt-intro":
      "A corporate social responsibility programme with two schools, twelve student teams and a judged competition, delivered in a town the team travelled to. The design work is above; this is the machinery that made it happen on schedule.",
    "project.cubico.mgmt-1-title": "1. Commitment, signed before starting",
    "project.cubico.mgmt-1-text":
      "Each school signed a participation agreement before kickoff: how many students were involved, in which year and inside which subject the programme would sit, the dates for teacher training and for the challenge itself, team size, minimum weekly hours, and which materials we would supply. A programme that depends on teachers who do not report to you is not held up by the enthusiasm of the first meeting, but by a signed document stating who provides what.",
    "project.cubico.mgmt-2-title": "2. A minute-by-minute run sheet, for someone else to deliver",
    "project.cubico.mgmt-2-text":
      "We did not run the sessions: the teachers at each school did. So the content was handed over as a minute-by-minute run sheet, every block detailed with its start time, duration, topic, activity description, materials needed and the expected outcome of that stretch, plus links to explainer videos for each activity. Designing something for someone else to deliver demands a level of detail that designing it for yourself never does.",
    "project.cubico.mgmt-3-title": "3. Competition rules, published before competing",
    "project.cubico.mgmt-3-text":
      "The acceptance conditions were settled and communicated before anyone submitted anything: which problems qualified, the deadline, the required deliverables, who could enter, and the substantive conditions every solution had to meet — implementable within six months, renewable energy at its core, social and environmental impact on the town, a genuinely fresh angle, and built with the methodology taught. Writing the rules first saves arguing about them later, once there is a winner.",
    "project.cubico.mgmt-4-title": "4. A weighted scoring system, not a show of hands",
    "project.cubico.mgmt-4-text":
      "The jury was seven people from five different organisations: the company, the town council, the local community, the two schools and the consultancy. A group like that does not reach a defensible decision by voting. We built a scoring sheet with seven weighted criteria — social impact, environmental impact, originality, feasibility split into implementability, time and budget, relevance to the energy challenge, and desirability for the community — each scored 1 to 5 against a written rubric. Every member scored independently within a fixed window, and the result came from the weighted average.",
    "project.cubico.mgmt-5-title": "5. Budget, suppliers and closing logistics",
    "project.cubico.mgmt-5-text":
      "The programme closed with an in-person awards event, and that brings its own management: quotes compared across suppliers, catering, venue, and the team travel. A corporate social responsibility project is also judged by how it looks on the day the client and the whole town are watching.",
    "project.cubico.mgmt-6-title": "6. The calendar, built backwards",
    "project.cubico.mgmt-6-text":
      "The whole plan was anchored to the awards date and built backwards from there: the ceremony first, then the jury evaluation window, then submission, then the four weeks of team work, then teacher training, and before all of it the signing of the agreements. When the end date cannot move because a public event has been announced, it is the only kind of planning that does not lie.",

    "project.cubico.methodology-title": "Design Thinking Adaptation",
    "project.cubico.methodology-intro":
      'The entire program was a careful adaptation of Design Thinking methodology to the educational context. It wasn\'t simply about "teaching" Design Thinking, but creating an experience where young people lived the complete process:',
    "project.cubico.methodology-empathize-title": "🔍 Empathize",
    "project.cubico.methodology-empathize-text":
      "Initial workshops with the community allowed students to understand real problems in their environment, not abstract or theoretical problems.",
    "project.cubico.methodology-define-title": "🎯 Define",
    "project.cubico.methodology-define-text":
      "With pedagogical tools, teams learned to synthesize information and focus their efforts on specific, actionable problems.",
    "project.cubico.methodology-ideate-title": "💡 Ideate",
    "project.cubico.methodology-ideate-text":
      "The interactive game board facilitated collaborative ideation sessions, fostering creativity without losing focus on sustainability.",
    "project.cubico.methodology-prototype-title": "🛠️ Prototype",
    "project.cubico.methodology-prototype-text":
      "Students developed tangible prototypes of their solutions, learning about iteration and continuous improvement.",
    "project.cubico.methodology-test-title": "🧪 Test",
    "project.cubico.methodology-test-text":
      "Final presentations functioned as validation moments, where they received feedback from teachers, peers, and Cubico representatives.",

    "project.cubico.result-1-value": "Teachers trained in Design Thinking",
    "project.cubico.result-2-value": "Participating students (ESO + VT)",
    "project.cubico.result-3-value": "Sustainable projects developed",
    "project.cubico.result-4-value": "Winning project implemented",

    "project.cubico.impact-1": "Training of 12 teachers in people-centered design methodologies",
    "project.cubico.impact-2": "Active participation of 85 ESO and Vocational Training students",
    "project.cubico.impact-3": "Development and presentation of 12 projects focused on sustainable solutions",
    "project.cubico.impact-4": "Implementation of winning project, with tangible benefits for the local community",
    "project.cubico.impact-5": "Program integration into school curriculum of both schools",
    "project.cubico.impact-6": "Strengthening of young people's commitment to sustainable development of their community",
    "project.cubico.impact-7": "Reusable pedagogical tools for future program editions",

    "project.cubico.reflection-quote": "The power of strategic and participatory design to generate social impact.",
    "project.cubico.reflection-1":
      "This project reaffirmed my conviction about the power of strategic and participatory design to generate social impact. It was inspiring to see how, through appropriate tools and a collaborative approach, young people can become protagonists of change in their communities.",
    "project.cubico.reflection-2":
      "Working with teachers was especially enriching: it wasn't just about giving them a pedagogical \"kit,\" but co-creating with them, respecting their knowledge of the educational context and adapting our methodologies to their realities. Seeing how they embraced Design Thinking and made it their own was one of the project's greatest achievements.",
    "project.cubico.reflection-3":
      "Additionally, it strengthened my ability to adapt design methodologies to diverse educational and cultural contexts. I learned that designing for education isn't just creating content, but creating experiences that transform the way young people and teachers relate to problems in their environment.",
    "project.cubico.reflection-4":
      "Seeing the winning project implemented and generate real benefits in Morón de la Frontera was confirmation that when we empower people with design tools, they don't just solve problems: they create possible futures.",

